	/**
	 * Check if a value looks like a phone number.
	 *
	 * Accepts various phone formats including:
	 * - US: (555) 123-4567, 555-123-4567, 5551234567
	 * - International: +1 555 123 4567, +44 20 7946 0958
	 * - Extensions: 555-123-4567 x1234, 555-123-4567 ext. 1234
	 *
	 * @since 2.8.0
	 *
	 * @param {string} value The value to check
	 * @return {boolean} True if the value looks like a phone number
	 */
	looksLikePhone( value ) {
		if ( ! value || typeof value !== 'string' ) {
			return true; // Empty values are allowed
		}

		const trimmedValue = value.trim();
		if ( trimmedValue === '' ) {
			return true; // Empty values are allowed
		}

		// Remove all common phone formatting characters for digit count
		const digitsOnly = trimmedValue.replace( /[\s\-\.\(\)\+]/g, '' );

		// Must have at least 7 digits (local number) and no more than 15 (international max)
		const digitCount = ( digitsOnly.match( /\d/g ) || [] ).length;
		if ( digitCount < 7 || digitCount > 15 ) {
			return false;
		}

		// Check for non-phone characters (letters except x for extension, or special chars)
		// Allow: digits, spaces, dashes, dots, parentheses, plus sign, and x/ext for extensions
		const invalidCharsPattern = /[^\d\s\-\.\(\)\+xXeEtT]/;
		if ( invalidCharsPattern.test( trimmedValue ) ) {
			return false;
		}

		// If we have letters, they should only be part of "ext" or "x" for extension
		const letters = trimmedValue.match( /[a-zA-Z]+/g );
		if ( letters ) {
			const validExtensionPatterns = /^(x|ext|extension)$/i;
			for ( const letter of letters ) {
				if ( ! validExtensionPatterns.test( letter ) ) {
					return false;
				}
			}
		}

		return true;
	}

