	/**
	 * Check if a value looks like an IPv4 or IPv6 address.
	 *
	 * @since 2.8.0
	 *
	 * @param {string} value The value to check
	 * @return {boolean} True if the value looks like a valid IP address
	 */
	looksLikeIp( value ) {
		if ( ! value || typeof value !== 'string' ) {
			return true; // Empty values are allowed
		}

		const trimmedValue = value.trim();
		if ( trimmedValue === '' ) {
			return true; // Empty values are allowed
		}

		const ipv4Pattern = /^(?:\d{1,3}\.){3}\d{1,3}$/;
		if ( ipv4Pattern.test( trimmedValue ) ) {
			const parts = trimmedValue.split( '.' ).map( part => parseInt( part, 10 ) );
			return parts.length === 4 && parts.every( part => part >= 0 && part <= 255 );
		}

		const ipv6Pattern = new RegExp(
			'^(' +
			'([0-9A-Fa-f]{1,4}:){7}([0-9A-Fa-f]{1,4}|:)|' +
			'([0-9A-Fa-f]{1,4}:){1,7}:|' +
			'([0-9A-Fa-f]{1,4}:){1,6}:[0-9A-Fa-f]{1,4}|' +
			'([0-9A-Fa-f]{1,4}:){1,5}(:[0-9A-Fa-f]{1,4}){1,2}|' +
			'([0-9A-Fa-f]{1,4}:){1,4}(:[0-9A-Fa-f]{1,4}){1,3}|' +
			'([0-9A-Fa-f]{1,4}:){1,3}(:[0-9A-Fa-f]{1,4}){1,4}|' +
			'([0-9A-Fa-f]{1,4}:){1,2}(:[0-9A-Fa-f]{1,4}){1,5}|' +
			'[0-9A-Fa-f]{1,4}:((:[0-9A-Fa-f]{1,4}){1,6})|' +
			':((:[0-9A-Fa-f]{1,4}){1,7}|:)|' +
			'fe80:(:[0-9A-Fa-f]{0,4}){0,4}%[0-9a-zA-Z]{1,}|' +
			'::(ffff(:0{1,4}){0,1}:){0,1}' +
			'((25[0-5]|(2[0-4]|1{0,1}[0-9])?[0-9])\\.){3}' +
			'(25[0-5]|(2[0-4]|1{0,1}[0-9])?[0-9])|' +
			'([0-9A-Fa-f]{1,4}:){1,4}:' +
			'((25[0-5]|(2[0-4]|1{0,1}[0-9])?[0-9])\\.){3}' +
			'(25[0-5]|(2[0-4]|1{0,1}[0-9])?[0-9])' +
			')$',
		);

		return ipv6Pattern.test( trimmedValue );
	}

