	/**
	 * Get the first non-numeric value in a column mapped to a number field
	 *
	 * @param {number} columnIndex The column index
	 * @param {Array} importData The import data
	 * @return {string|null} The first invalid value, or null if all values are valid
	 */
	getFirstInvalidNumber( columnIndex, importData ) {
		// Check sample data (skip header row)
		for ( let i = 1; i < Math.min( importData.length, 11 ); i++ ) {
			const value = importData[ i ] && importData[ i ][ columnIndex ];

			// Skip empty values - they're allowed
			if ( value === null || value === undefined || value === '' ) {
				continue;
			}

			const stringValue = String( value ).trim();

			// Skip empty strings after trim
			if ( stringValue === '' ) {
				continue;
			}

			// Check if it's a valid number (including negative, decimals, and currency formats)
			// Remove common number formatting: commas, currency symbols, spaces
			const cleanedValue = stringValue
				.replace( /[$€£¥₹,\s]/g, '' )  // Remove currency symbols, commas, spaces
				.replace( /^[+-]/, '' );        // Remove leading +/- for validation

			// Check if the cleaned value is a valid number
			if ( cleanedValue !== '' && isNaN( parseFloat( cleanedValue ) ) ) {
				return stringValue;
			}

			// Also catch values that have numbers but aren't purely numeric (like "5abc")
			if ( cleanedValue !== '' && ! /^-?\d*\.?\d+$/.test( cleanedValue ) ) {
				return stringValue;
			}
		}

		return null;
	}

